        tzf_faq_title: "Common Questions About Terrazzo",
        tzf_faq_q1: "What's the difference between cement and epoxy terrazzo?",
        tzf_faq_a1: "Cement terrazzo is the traditional system — thicker (25-50mm), requires a sand-cement bed, and suits new construction. Epoxy terrazzo is thin-set (10-12mm), applied directly to concrete, and ideal for renovation. Both offer comparable aesthetics and durability; the choice depends on project constraints.",
        tzf_faq_q2: "Is terrazzo really worth the higher cost?",
        tzf_faq_a2: "When evaluated over lifecycle, yes. Initial costs are higher, but terrazzo lasts 50+ years with minimal maintenance. It's restorable, not replaceable. Many terrazzo floors installed decades ago are still in service — the math favors terrazzo for permanent installations.",
        tzf_faq_q3: "How customizable is the design?",
        tzf_faq_a3: "Almost unlimited. Aggregate types (marble, glass, shell, recycled materials), sizes, colors, and matrix tints are all variable. Divider strips create patterns, logos, and wayfinding. We work with architects to realize virtually any design vision.",
        tzf_faq_q4: "Can old terrazzo floors be restored?",
        tzf_faq_a4: "Yes — this is one of terrazzo's great advantages. Worn or damaged floors can be reground and repolished to original condition. Cracks and chips are repairable with matching materials. Restoration is typically far more cost-effective than replacement.",
        tzf_faq_q5: "Is terrazzo slippery?",
        tzf_faq_a5: "Polished terrazzo has moderate slip resistance suitable for most commercial environments. For areas requiring higher slip ratings (entrances, wet areas), we use aggregates and finishes that achieve the required coefficients while maintaining aesthetic appeal.",
        tzf_faq_q6: "How long does terrazzo installation take?",
        tzf_faq_a6: "Terrazzo requires patience. The process involves pouring, curing (7-14 days), multiple grinding passes, grouting, and polishing. A typical project takes 3-4 weeks from start to completion. This is an investment in permanent quality, not a quick fix.",
