        epf_faq_q1: "How long does epoxy flooring last?",
        epf_faq_a1: "With proper installation and maintenance, epoxy flooring typically lasts 10-20 years in industrial environments. In lighter commercial or residential settings, it can last even longer. Key factors are substrate preparation quality and choosing the right system for your specific conditions.",
        epf_faq_q2: "How long before we can use the floor after installation?",
        epf_faq_a2: "Light foot traffic is typically possible after 24 hours. Full mechanical loading (forklifts, heavy equipment) requires 7 days for standard systems. Fast-cure formulations can reduce this significantly when downtime is critical.",
        epf_faq_q3: "Can epoxy be applied over existing tiles or coatings?",
        epf_faq_a3: "In most cases, yes — but it depends on the condition of the existing surface. Old coatings must be tested for adhesion and compatibility. Tiles can be overlaid if they're well-bonded and don't have excessive moisture. We assess each situation during site inspection.",
        epf_faq_q4: "Is epoxy flooring slippery when wet?",
        epf_faq_a4: "Standard smooth epoxy can be slippery when wet. For areas with water, oils, or other liquids, we specify textured aggregate systems and agree the cleanability vs grip tradeoff before installation.",
        epf_faq_q5: "What causes epoxy floors to fail?",
        epf_faq_a5: "The most common causes are: poor substrate preparation (80% of failures), moisture issues in the concrete, incorrect system selection for the environment, and applying over contaminated surfaces. This is why we invest heavily in surface preparation and testing.",
        epf_faq_q6: "Can damaged epoxy floors be repaired?",
        epf_faq_a6: "Yes. Localized damage can be repaired by grinding out the affected area and patching with compatible materials. For extensive wear, a full recoat can restore the floor to new condition. Repairs are one of epoxy's advantages over alternatives.",
