        pucf_7: "Honest decision",
        pucf_8: "Is PU-Cement right for your project?",
        pucf_9: "Good fit",
        pucf_10: "Food/beverage processing, dairies, breweries, meat & fish plants",
        pucf_11: "Spaces with thermal cycling (cold rooms, hot wash-downs)",
