        pucf_20: "Existing coatings — full removal usually needed",
        pucf_21: "Drainage channels and coving plan before pour",
        pucf_22: "Operational schedule: short downtime is the win",
        pucf_23: "Spec at a glance",
        pucf_24: "PU-Cement decision specs",
        pucf_25: "Substrate moisture",
        pucf_26: "Tolerant of damp substrates (up to 6%)",
        pucf_27: "Load class",
        pucf_28: "Heavy industrial — forklifts, drum drops, wheeled loads",
        pucf_29: "Realistic downtime",
        pucf_30: "2–4 days; faster than full epoxy chemical cure",
        pucf_31: "Thermal range",
        pucf_32: "−40 °C to +120 °C with appropriate system",
        pucf_33: "Chemical exposure",
        pucf_34: "Strong — designed for food/beverage processing",
        pucf_35: "System buildup",
        pucf_36: "Primer + 6–9 mm body + topcoat",
        pucf_37: "Warranty",
        pucf_38: "System-specific; documented in project proposal",
        pucf_39: "Real numbers depend on substrate, environment and selected system family. We confirm everything before quoting.",
        pucf_40: "FAQ",
        pucf_41: "Common Questions About PU-Cement Floors",
        pucf_42: "Why choose PU-cement over epoxy?",
        pucf_43: "PU-cement is specifically designed for environments with thermal shock — hot wash-downs, steam cleaning, freezer interfaces. Standard epoxy can crack under these conditions. If your facility requires daily hot water cleaning or has temperature extremes, PU-cement is the right choice.",
        pucf_44: "Can PU-cement support food-safety audits?",
        pucf_45: "PU-cement is commonly used in food and beverage environments because it can be detailed as a seamless, cleanable system with coves and drainage. Final compliance depends on the selected product, specification and site audit requirements.",
        pucf_46: "How thick is a PU-cement floor?",
        pucf_47: "Typically 6-9mm, significantly thicker than epoxy (2-5mm). This thickness provides impact resistance, thermal mass for temperature cycling, and allows for integral falls to drain. The thickness is a feature, not a limitation.",
        pucf_48: "Can PU-cement be installed over existing floors?",
        pucf_49: "Usually existing coatings need to be removed down to concrete. The system requires aggressive mechanical bonding and often needs screeding to achieve proper drainage falls. We assess overlay feasibility during site inspection.",
        pucf_50: "How slippery is PU-cement when wet?",
        pucf_51: "PU-cement comes in multiple texture levels. We specify grip based on water, grease, slope, drainage and cleaning method, because heavier texture improves grip but requires more cleaning effort.",
        pucf_52: "What's the installation process for an operating facility?",
        pucf_53: "We typically install in phases to minimize disruption. Weekend work is common. The system cures quickly (24-48 hours to traffic), so areas can return to production rapidly. Full project planning coordinates with your production schedule.",
        pucf_54: "Related Systems",
        pucf_55: "Explore Other Options",
        pucf_56: "Epoxy",
        pucf_57: "For environments without thermal shock requirements.",
        pucf_58: "MMA Resin",
        pucf_59: "Rapid cure for minimal downtime installations.",
        pucf_60: "Microtopping",
        pucf_61: "Decorative cement for front-of-house areas.",
        // Material fit-cards: microtopping
        mtf_1: "Honest decision",
        mtf_2: "Is Microtopping right for your project?",
        mtf_3: "Good fit",
        mtf_4: "Indoor decorative floors (showrooms, residential, boutique retail)",
        mtf_5: "Renovations where lifting existing floor is not an option",
        mtf_6: "Architects looking for seamless concrete look on existing slab",
        mtf_7: "Light commercial pedestrian traffic",
        mtf_8: "Not a fit",
        mtf_9: "Industrial loads (forklifts, heavy wheeled equipment)",
        mtf_10: "Substrates with active cracks — they telegraph through thin overlay",
        mtf_11: "High-traffic outdoor areas with freeze-thaw",
        mtf_12: "Areas with frequent acidic cleaning agents",
        mtf_13: "Inspect first",
        mtf_14: "Substrate cracks — must be stabilised first",
        mtf_15: "Existing floor adhesion (laitance, paint, glue residue)",
        mtf_16: "Substrate flatness — overlay follows geometry, no leveling",
        mtf_17: "Realistic acceptance of hairline cracking as part of material character",
        mtf_18: "Spec at a glance",
        mtf_19: "Microtopping decision specs",
        mtf_20: "Substrate moisture",
        mtf_21: "≤ 4% — substrate must be sound; existing cracks must be repaired before overlay",
        mtf_22: "Load class",
        mtf_23: "Light pedestrian / commercial; not for forklift or wheel-load environments",
        mtf_24: "Realistic downtime",
        mtf_25: "5–10 days from prep to sealed finish",
        mtf_26: "Thermal range",
        mtf_27: "Indoor service; sensitive to extreme freeze–thaw if exterior",
        mtf_28: "Chemical exposure",
        mtf_29: "Mild — sealed surface; avoid acidic cleaners",
        mtf_30: "System buildup",
        mtf_31: "Primer + 2–3 mm overlay (2–3 layers) + sealer",
        mtf_32: "Warranty",
        mtf_33: "System-specific; documented in project proposal",
        mtf_34: "Real numbers depend on substrate, environment and selected system family. We confirm everything before quoting.",
        mtf_35: "FAQ",
        mtf_36: "Common Questions About Microtopping",
        mtf_37: "Can microtopping go over my existing tiles?",
        mtf_38: "Yes, in most cases. The tiles must be well-bonded to the substrate without excessive movement or cracks. Grout lines are filled and the surface is prepared for optimal adhesion. This is one of microtopping's key advantages — renovation without demolition.",
        mtf_39: "Will the floor crack?",
        mtf_40: "Microtopping follows the behavior of the substrate beneath it. Hairline cracks can appear, especially over existing cracks or at movement joints — this is normal and considered part of the material's character. Fiberglass reinforcement minimizes this, and cracks can be touched up if needed.",
        mtf_41: "Is microtopping suitable for bathrooms and wet areas?",
        mtf_42: "Yes, when properly sealed. The polyurethane sealer provides water resistance. For shower floors and direct wet areas, we recommend additional waterproofing membranes beneath the microtopping and non-slip texture options.",
        mtf_43: "How does microtopping work with underfloor heating?",
        mtf_44: "Excellently. At 2-3mm thickness, microtopping is thinner than tiles, providing faster heat response and better efficiency. The system is fully compatible with both water and electric underfloor heating. We specify cure times to avoid thermal shock.",
        mtf_45: "What maintenance does microtopping require?",
        mtf_46: "Daily dust mopping, weekly damp mopping with neutral pH cleaner. Avoid harsh chemicals and abrasives. The sealer protects the surface — expect to recoat high-traffic areas every 2-3 years, with full resealing every 5-7 years depending on use.",
        mtf_47: "Can I choose the exact color?",
        mtf_48: "Microtopping is pigmented, so color ranges are available. However, due to the hand-applied nature and natural cement variations, exact color matching isn't possible. Each floor has subtle tonal variations — this is part of the artisanal character. We provide sample panels before installation.",
        mtf_49: "Related Systems",
        mtf_50: "Explore Other Options",
        mtf_51: "Terrazzo",
