        // PU-Cement
        puc_category: "Thermal Shock Resistant",
        puc_title: "PU-Cement Flooring",
        puc_meta: "Polyurethane-Cement Hybrid Systems",
        puc_lead: "Polyurethane-cement hybrid systems engineered for extreme thermal cycling. From boiling water to freezer temperatures — without cracking. The industry standard for food and beverage processing.",
        puc_h2_where: "Where PU-Cement Performs",
        puc_p_where: "PU-cement is the only flooring system specifically designed for the demands of food processing environments where thermal shock, aggressive cleaning, and hygiene requirements converge.",
        puc_app1_title: "Food & Beverage Processing",
        puc_app1_desc: "Breweries, dairies, meat processing. Hot wash-downs, caustic cleaning, steam exposure. The industry standard.",
        puc_app2_title: "Commercial Kitchens",
        puc_app2_desc: "Hot oil spills, boiling water, constant cleaning. Texture is selected for wet environments and cleaning method.",
        puc_app3_title: "Pharmaceutical",
        puc_app3_desc: "Clean-in-place compatible. Withstands aggressive sanitization protocols.",
        puc_app4_title: "Bakeries & Laundries",
        puc_app4_desc: "Hot oven interfaces, steam exposure, constant moisture, detergent resistance.",
        puc_h2_built: "Built for Abuse",
        puc_p_built: "PU-cement systems are thick-build mortars that require proper drainage design and substrate preparation for optimal performance.",
        puc_prep1: "<strong>Falls to drain</strong> — Minimum 1:80 fall required. We install screeds to create proper drainage",
        puc_prep2: "<strong>Shot blasting</strong> — Aggressive profile (CSP 5-7) for mechanical bond to substrate",
        puc_prep3: "<strong>Coved skirting</strong> — Integral cove at wall junctions eliminates corner joints",
        puc_prep4: "<strong>Channel drains</strong> — Stainless steel drainage integrated into floor system",
        puc_prep5: "<strong>Moisture tolerance</strong> — PU-cement is moisture-tolerant but excess water should be addressed",
        puc_h2_system: "System Architecture",
        puc_p_system: "PU-cement systems combine the strength of cement with the flexibility and chemical resistance of polyurethane.",
        puc_layer1_title: "Bonding System",
        puc_layer1_desc: "Epoxy or polyurethane primer creates chemical bond to prepared concrete. Critical for adhesion under thermal stress.",
        puc_layer2_title: "PU-Cement Mortar",
        puc_layer2_desc: "Polyurethane-bound cementitious mortar troweled to specified thickness. Contains special aggregates for thermal stability and wear resistance.",
        puc_layer3_title: "Seal Coat",
        puc_layer3_desc: "Polyurethane topcoat seals surface, provides chemical resistance, and determines slip texture level.",
        puc_h2_texture: "Texture Options",
        puc_p_texture: "Slip resistance is critical in wet food processing environments. We offer the full range of textures:",
        puc_var1_title: "Smooth (R10)",
        puc_var1_desc: "Easy to clean, moderate slip resistance. Dry processing areas.",
        puc_var2_title: "Medium (R11)",
        puc_var2_desc: "Balanced cleanability and grip. Most food processing applications.",
        puc_var3_title: "Coarse (R12)",
        puc_var3_desc: "Higher slip resistance for wet/oily areas. Slightly more effort to clean.",
        puc_var4_title: "Heavy Duty (R13)",
        puc_var4_desc: "Maximum grip for extreme wet conditions. Industrial drainage areas.",
        puc_h2_advantages: "Key Advantages",
        puc_adv1: "<strong>Thermal Shock Resistance</strong> — Built for hot wash-downs, cold rooms and temperature cycling when the correct thickness is specified.",
        puc_adv2: "<strong>Steam & Hot Water</strong> — Designed for daily steam cleaning and hot wash-downs. Industry standard for food processing.",
        puc_adv3: "<strong>Chemical Resistance</strong> — Resists many organic acids, caustics and cleaning chemicals when matched to the exposure list.",
        puc_adv4: "<strong>Texture Options</strong> — Grip is matched to water, grease, drainage and cleaning requirements.",
        puc_adv5: "<strong>Impact Resistant</strong> — High-build mortar absorbs impact. Dropped equipment, pallet trucks, heavy loads.",
        puc_adv6: "<strong>Cleanable Design</strong> — Seamless field with coved skirting and drainage detailing where specified.",
        puc_h2_maintenance: "Maintenance Protocol",
        puc_p_maintenance: "PU-cement is specifically designed for aggressive cleaning regimes. The system gets better with regular cleaning.",
        puc_maint_shift: "Production Shift End",
        puc_maint_shift_desc: "Hot water wash-down, detergent scrub, rinse. Floor designed for this daily cycle.",
        puc_maint_weekly: "Deep clean with appropriate chemicals. Caustic or acid as required by product.",
        puc_maint_quarterly: "Inspection of drains, coves, and high-wear areas. Touch-up repairs as needed.",
        puc_maint_annually: "Full system inspection. Reseal high-traffic areas if required.",
        puc_cta_title: "Food Processing Floor Project?",
        puc_cta_text: "Our team specializes in HACCP-compliant floor systems for demanding environments.",
        puc_specs_title: "Technical Specifications",
        puc_spec_thickness: "System Thickness",
        puc_spec_shock: "Thermal Shock",
        puc_spec_shock_v: "Unlimited cycles",
        puc_spec_impact: "Impact Resistance",
        puc_slip_title: "Slip Resistance",
        puc_slip_smooth: "Smooth Finish",
        puc_slip_medium: "Medium Finish",
        puc_slip_coarse: "Coarse Finish",
        puc_slip_heavy: "Heavy Duty",
