        rest_var4_title: "Historic Terrazzo",
        rest_var4_desc: "Decades-old terrazzo ground, polished, and sealed. Reveals original beauty.",
        rest_h2_advantages: "Key Advantages",
        rest_adv1: "<strong>Cost Effective</strong> — 50-70% of replacement cost. Extends floor life at fraction of new installation price.",
        rest_adv2: "<strong>Less Downtime</strong> — Typically 1-3 days vs. 1-2 weeks for full replacement. Business continues faster.",
        rest_adv3: "<strong>Sustainable</strong> — Keeps existing floor out of landfill. Minimal new materials required.",
        rest_adv4: "<strong>No Demolition</strong> — No removal of existing floor. Less disruption, noise, and waste.",
        rest_adv5: "<strong>Upgrade Opportunity</strong> — Can upgrade to better topcoat, add slip resistance, or change color during restoration.",
        rest_adv6: "<strong>Preventive Maintenance</strong> — Regular recoating prevents wear-through to substrate. Extends total floor lifespan.",
