        tzf_spec_warranty_label: "Гарантия",
        tzf_spec_warranty_value: "Зависит от системы; фиксируется в коммерческом предложении",
        tzf_spec_note: "Реальные цифры зависят от основания, условий эксплуатации и выбранного семейства системы. Мы подтверждаем все параметры до расчёта стоимости.",
        tzf_faq_subtitle: "Частые вопросы",
        tzf_faq_title: "Частые вопросы о терраццо",
        tzf_faq_q1: "В чём разница между цементным и эпоксидным терраццо?",
        tzf_faq_a1: "Цементное терраццо — традиционная система: толще (25–50 мм), требует песчано-цементной стяжки и подходит для нового строительства. Эпоксидное терраццо — тонкослойное (10–12 мм), наносится прямо на бетон и идеально для реконструкции. Эстетика и долговечность сопоставимы; выбор зависит от условий проекта.",
        tzf_faq_q2: "Действительно ли терраццо оправдывает свою цену?",
        tzf_faq_a2: "С точки зрения срока службы — да. Стартовые затраты выше, но терраццо служит 50+ лет при минимальном уходе. Его восстанавливают, а не меняют. Многие полы из терраццо, уложенные десятилетия назад, в строю до сих пор — для постоянных решений расчёт в его пользу.",
        tzf_faq_q3: "Насколько гибок дизайн?",
        tzf_faq_a3: "Практически безграничен. Тип наполнителя (мрамор, стекло, ракушка, переработанные материалы), размер, цвет и оттенок матрицы — всё варьируется. Разделительные рейки создают узоры, логотипы и навигацию. Мы работаем с архитекторами и реализуем практически любую дизайн-идею.",
        tzf_faq_q4: "Можно ли восстановить старый пол из терраццо?",
        tzf_faq_a4: "Да — это одно из главных преимуществ терраццо. Изношенный или повреждённый пол можно заново отшлифовать и отполировать до исходного состояния. Трещины и сколы ремонтируются подобранными материалами. Восстановление обычно гораздо выгоднее замены.",
        tzf_faq_q5: "Скользкое ли терраццо?",
        tzf_faq_a5: "Полированное терраццо имеет умеренное сопротивление скольжению, достаточное для большинства коммерческих помещений. Для зон с повышенными требованиями (входы, влажные участки) мы подбираем наполнители и финиши, обеспечивающие нужный коэффициент без потери эстетики.",
        tzf_faq_q6: "Сколько времени занимает укладка терраццо?",
        tzf_faq_a6: "Терраццо требует терпения. Процесс включает заливку, набор прочности (7–14 дней), несколько проходов шлифовки, заполнение пор и полировку. Типовой проект занимает 3–4 недели от старта до сдачи. Это вложение в долговечное качество, а не быстрое решение.",
        tzf_related_subtitle: "Смежные системы",
        tzf_related_title: "Другие решения",
