        epf_inspect_4: "Прочность бетона — слабые и пылящие поверхности требуют упрочнения",
        epf_faq_subtitle: "Частые вопросы",
        epf_faq_title: "Частые вопросы об эпоксидных полах",
        epf_faq_q1: "Сколько служит эпоксидный пол?",
        epf_faq_a1: "При правильной укладке и уходе эпоксидный пол в промышленных условиях служит обычно 10–20 лет. В более лёгких коммерческих или жилых условиях — дольше. Ключевые факторы — качество подготовки основания и правильный выбор системы под конкретные условия.",
        epf_faq_q2: "Когда можно пользоваться полом после укладки?",
        epf_faq_a2: "Лёгкое пешее движение обычно возможно через 24 часа. Полная механическая нагрузка (погрузчики, тяжёлая техника) требует 7 дней для стандартных систем. Быстротвердеющие составы заметно сокращают этот срок, когда простой критичен.",
        epf_faq_q3: "Можно ли наносить эпоксид поверх старой плитки или покрытия?",
        epf_faq_a3: "В большинстве случаев да — но всё зависит от состояния существующей поверхности. Старые покрытия проверяются на адгезию и совместимость. Плитку можно перекрывать, если она прочно держится и нет избыточной влаги. Каждую ситуацию мы оцениваем при осмотре объекта.",
        epf_faq_q4: "Скользкий ли эпоксидный пол во влажном состоянии?",
        epf_faq_a4: "Гладкий эпоксид во влажном состоянии может быть скользким. Для зон с водой, маслами или другими жидкостями мы закладываем системы с текстурным наполнителем и заранее согласовываем баланс между лёгкостью уборки и сцеплением.",
        epf_faq_q5: "Из-за чего эпоксидные полы выходят из строя?",
        epf_faq_a5: "Самые частые причины: плохая подготовка основания (80% отказов), проблемы с влажностью бетона, неверный выбор системы под условия и нанесение на загрязнённые поверхности. Именно поэтому мы вкладываемся в подготовку поверхности и испытания.",
        epf_faq_q6: "Можно ли отремонтировать повреждённый эпоксидный пол?",
        epf_faq_a6: "Да. Локальные повреждения ремонтируются вышлифовкой проблемного участка и заделкой совместимыми материалами. При значительном износе полное перекрытие возвращает полу состояние нового. Ремонтопригодность — одно из преимуществ эпоксида перед альтернативами.",
        epf_related_subtitle: "Смежные системы",
