        pucf_37: "Гарантия",
        pucf_38: "Зависит от системы; фиксируется в проектном предложении",
        pucf_39: "Точные цифры зависят от основания, среды и выбранного семейства системы. Всё подтверждаем до расчёта стоимости.",
        pucf_40: "FAQ",
        pucf_41: "Частые вопросы о полах из ПУ-цемента",
        pucf_42: "Почему ПУ-цемент, а не эпоксид?",
        pucf_43: "ПУ-цемент специально создан для сред с термошоком — горячая мойка, паровая очистка, переходы в морозильные камеры. Обычный эпоксид в таких условиях может трескаться. Если на объекте ежедневная мойка горячей водой или экстремальные перепады температур — ПУ-цемент верный выбор.",
        pucf_44: "Подходит ли ПУ-цемент для аудитов пищевой безопасности?",
        pucf_45: "ПУ-цемент широко применяют в пищевых и напиточных производствах, потому что его можно сделать бесшовной, легко моющейся системой с галтелями и водоотводом. Итоговое соответствие зависит от выбранного продукта, спецификации и требований аудита объекта.",
        pucf_46: "Какой толщины пол из ПУ-цемента?",
        pucf_47: "Обычно 6–9 мм — заметно толще эпоксида (2–5 мм). Эта толщина даёт ударопрочность, тепловую массу для перепадов температур и позволяет сделать встроенные уклоны к трапам. Толщина — это преимущество, а не ограничение.",
        pucf_48: "Можно ли устроить ПУ-цемент поверх существующих полов?",
        pucf_49: "Обычно старые покрытия нужно удалить до бетона. Системе нужна агрессивная механическая адгезия, а часто и стяжка для создания правильных уклонов к трапам. Возможность укладки поверх оцениваем при осмотре объекта.",
        pucf_50: "Насколько ПУ-цемент скользкий во влажном состоянии?",
        pucf_51: "ПУ-цемент выпускается с несколькими уровнями текстуры. Сцепление подбираем под воду, жир, уклон, водоотвод и способ уборки — более грубая текстура улучшает сцепление, но требует больше усилий при мойке.",
        pucf_52: "Как идёт укладка на действующем производстве?",
        pucf_53: "Обычно укладываем поэтапно, чтобы минимизировать простой. Часто работаем по выходным. Система отверждается быстро (24–48 часов до нагрузки), поэтому участки быстро возвращаются в работу. Полное планирование проекта согласуется с вашим производственным графиком.",
        pucf_54: "Смежные системы",
        pucf_55: "Другие варианты",
        pucf_56: "Эпоксид",
        pucf_57: "Для сред без требований к стойкости к термошоку.",
        pucf_58: "ММА-смола",
