        mtf_26: "Температурный диапазон",
        mtf_27: "Для помещений; чувствителен к сильным циклам замораживания-оттаивания на улице",
        mtf_28: "Химическое воздействие",
        mtf_29: "Умеренное — поверхность под лаком; избегайте кислотных моющих средств",
        mtf_30: "Структура системы",
        mtf_31: "Грунт + слой 2–3 мм (2–3 слоя) + финишный лак",
        mtf_32: "Гарантия",
        mtf_33: "Зависит от системы; фиксируется в проектном предложении",
        mtf_34: "Реальные цифры зависят от основания, условий и выбранного семейства системы. Мы подтверждаем все параметры до расчёта стоимости.",
        mtf_35: "Вопросы и ответы",
        mtf_36: "Частые вопросы о микротопинге",
        mtf_37: "Можно ли нанести микротопинг поверх существующей плитки?",
        mtf_38: "Да, в большинстве случаев. Плитка должна быть прочно сцеплена с основанием, без излишней подвижности и трещин. Швы заполняются, поверхность подготавливается для оптимальной адгезии. Это одно из ключевых преимуществ микротопинга — ремонт без демонтажа.",
        mtf_39: "Будет ли пол трескаться?",
        mtf_40: "Микротопинг повторяет поведение основания под ним. Волосяные трещины могут появиться, особенно над существующими трещинами или на деформационных швах — это нормально и считается частью характера материала. Армирование стеклосеткой сводит это к минимуму, а трещины при необходимости можно подправить.",
        mtf_41: "Подходит ли микротопинг для ванных и влажных зон?",
        mtf_42: "Да, при правильной герметизации. Полиуретановый лак обеспечивает водостойкость. Для полов в душевых и зон с прямым контактом с водой мы рекомендуем дополнительную гидроизоляционную мембрану под микротопингом и противоскользящие варианты текстуры.",
        mtf_43: "Как микротопинг работает с тёплым полом?",
        mtf_44: "Отлично. При толщине 2–3 мм микротопинг тоньше плитки, обеспечивая более быстрый отклик на нагрев и большую эффективность. Система полностью совместима с водяным и электрическим тёплым полом. Мы задаём сроки набора прочности, чтобы избежать теплового удара.",
        mtf_45: "Какой уход требует микротопинг?",
        mtf_46: "Ежедневная сухая уборка, еженедельная влажная уборка с нейтральным pH-средством. Избегайте агрессивной химии и абразивов. Лак защищает поверхность — в зонах высокого трафика обновление слоя примерно раз в 2–3 года, полная повторная герметизация раз в 5–7 лет в зависимости от эксплуатации.",
        mtf_47: "Можно ли выбрать точный цвет?",
        mtf_48: "Микротопинг пигментируется, поэтому доступны цветовые гаммы. Однако из-за ручного нанесения и естественных вариаций цемента точное попадание в цвет невозможно. Каждый пол имеет лёгкие тональные переходы — это часть ремесленного характера. Перед монтажом мы предоставляем образцы.",
        mtf_49: "Смежные системы",
        mtf_50: "Другие варианты",
        mtf_51: "Терраццо",
        mtf_52: "Поверхности, богатые наполнителем, для декоративного эффекта.",
        mtf_53: "Декоративный бетон",
        mtf_54: "Полированные и тонированные бетонные финиши.",
        mtf_55: "Эпоксидные полы",
        mtf_56: "Высокоэффективные смоляные системы для тяжёлых условий.",
        mmf_1: "Подходит",
        mmf_2: "Холодные склады, переоснащение ретейла, ремонтные коридоры, объекты 24/7 и поэтапные проекты, где простой дороже стоимости материала.",
        mmf_3: "Не первый выбор",
        mmf_4: "Эксплуатируемые помещения с плохой вентиляцией, объекты, чувствительные к запаху, неизвестные основания или проекты, где допустим стандартный простой под эпоксид.",
        mmf_5: "Сначала проверить",
