        mmf_14: "Не подходит",
        mmf_15: "Объекты с плохой вентиляцией — сильный запах во время монтажа",
        mmf_16: "Основания с высокой влажностью (грунт чувствителен)",
        mmf_17: "Декоративные работы с длинным окном, где скорость не критична",
        mmf_18: "Жилые дома с проживанием — требования к запаху и вентиляции",
        mmf_19: "Сначала проверить",
        mmf_20: "Диапазон температуры воздуха (возможно до −30 °C)",
        mmf_21: "План вентиляции на время набора прочности (обязателен)",
        mmf_22: "Сухость основания — проверить до нанесения грунта",
        mmf_23: "Сертификация бригады — MMA требует обученных мастеров",
        mmf_24: "Характеристики кратко",
        mmf_25: "Ключевые параметры MMA",
        mmf_26: "Влажность основания",
        mmf_27: "Строго — основание должно быть сухим",
        mmf_28: "Класс нагрузки",
        mmf_29: "Промышленный / холодные склады; высокая стойкость к ударам",
        mmf_30: "Реальный простой",
        mmf_31: "Ввод в эксплуатацию в тот же день (набор прочности 1–3 часа)",
        mmf_32: "Температурный диапазон",
        mmf_33: "Монтаж возможен до −30 °C",
        mmf_34: "Химическое воздействие",
        mmf_35: "Отличная стойкость к промышленной химии",
        mmf_36: "Структура системы",
        mmf_37: "Грунт + основной слой + топ-слой; во время монтажа нужна вентиляция",
        mmf_38: "Гарантия",
        mmf_39: "Зависит от системы; фиксируется в проектном предложении",
        mmf_40: "Реальные цифры зависят от основания, условий и выбранного семейства системы. Мы подтверждаем все параметры до расчёта стоимости.",
        mmf_41: "Вопросы и ответы",
        mmf_42: "Частые вопросы о полах MMA",
        mmf_43: "Насколько быстро реально смонтировать MMA?",
        mmf_44: "MMA набирает прочность за 1–2 часа, то есть готовую систему можно смонтировать и подготовить к лёгкому трафику за 4–6 часов. Полная механическая нагрузка обычно возможна в течение 24 часов. Мы регулярно выполняем ночной монтаж для клиентов из ретейла и пищевой промышленности.",
        mmf_45: "Что насчёт запаха во время монтажа?",
        mmf_46: "У MMA характерный запах при нанесении (похож на средства для акриловых ногтей). Он быстро выветривается после набора прочности — обычно за несколько часов. Для чувствительных сред вроде больниц мы используем составы с пониженным запахом и тщательно согласуем вентиляцию.",
        mmf_47: "Можно ли смонтировать MMA в холодном складе, не освобождая его?",
        mmf_48: "Иногда, после оценки рисков для конкретного объекта. MMA работает при низких температурах, но доступ, гигиену, безопасность продукции, вентиляцию и стабильность температуры нужно спланировать до любого монтажа в действующей холодной камере.",
        mmf_49: "Как MMA сравнивается с эпоксидом по долговечности?",
        mmf_50: "MMA и эпоксид имеют схожие механические свойства при правильном составе. MMA более эластичен (лучше перекрывает волосяные трещины), более UV-стабилен (подходит для улицы), но немного уступает по химстойкости специализированным эпоксидным системам. Для большинства задач они работают сопоставимо.",
        mmf_51: "MMA дороже эпоксида?",
        mmf_52: "Стоимость материала обычно выше. Однако с учётом сокращённого простоя, более быстрого возврата к производству и возможности монтажа в сложных условиях MMA нередко даёт большую итоговую ценность проекта. Для каждого проекта мы предоставляем подробный расчёт затрат.",
        mmf_53: "Легко ли ремонтировать повреждённые участки?",
        mmf_54: "Да — быстрый набор прочности MMA делает ремонт особенно удобным. Небольшие участки можно сошлифовать и заделать за несколько часов. Новый материал химически сцепляется с существующим полом. Ремонт не требует длительного простоя.",
        mmf_55: "Смежные системы",
        mmf_56: "Другие варианты",
        mmf_57: "Эпоксидные полы",
        mmf_58: "Системы стандартного отверждения для максимальной химстойкости.",
        mmf_59: "ПУ-цемент",
        mmf_60: "Стойкость к тепловому удару для пищевой промышленности и напитков.",
        mmf_61: "Резиновые полы",
        mmf_62: "Комфорт и безопасность для пространств, ориентированных на людей.",

