        sticky_cta: "WhatsApp",

        // About Page
        about_hero_overline: "О компании",
        about_hero_title: "Инженерное<br>совершенство",
        about_hero_desc: "Floor.DSGN реализует профессиональные напольные решения инженерного класса по всему Израилю. Мы сочетаем европейские материалы с точным монтажом, создавая полы, которые работают и вдохновляют.",
        about_values_overline: "Наш подход",
        about_values_title: "Что нами движет",
        about_value1_title: "Техническое совершенство",
        about_value1_desc: "Каждый проект начинается с тщательного анализа основания и подбора системы. Мы подбираем оптимальное напольное покрытие под ваши условия эксплуатации и требования к производительности.",
        about_value2_title: "Качественные материалы",
        about_value2_desc: "Мы работаем исключительно с ведущими европейскими производителями — немецкие, итальянские и швейцарские системы с подтверждённой репутацией в сложных условиях эксплуатации.",
        about_value3_title: "Точный монтаж",
        about_value3_desc: "Монтаж строится вокруг документированной подготовки, спецификаций производителя и реальных условий объекта.",
        about_story_overline: "Наша история",
        about_story_title: "Основано на экспертизе",
        about_story_p1: "Floor.DSGN была основана инженерами-полимерщиками, которые увидели пробел на израильском рынке: потребность в действительно технических напольных решениях с архитектурным подходом.",
        about_story_p2: "Сегодня мы работаем с промышленными предприятиями, коммерческими застройщиками, архитекторами и владельцами жилья, которые требуют надёжность без компромиссов в эстетике. От заводской эпоксидки до ручного терраццо — мы делаем полы, которые работают.",
        about_story_p3: "Наша команда сочетает глубокие знания материаловедения с практическим опытом монтажа. Мы не просто продаём системы — мы проектируем решения.",
        about_team_overline: "Наша команда",
        about_team_title: "Наши специалисты",
        about_team_desc: "Технические специалисты с практическим опытом в инженерии напольных покрытий.",
