        about_team1_desc: "Многолетний опыт в области полимерных напольных систем. Бывший технический консультант европейских производителей.",
        about_team2_name: "Михаэль Леви",
        about_team2_role: "Руководитель монтажного отдела",
        about_team2_desc: "Руководитель монтажа с экспертизой в терраццо и декоративных системах.",
        about_team3_name: "Анна Шапиро",
