        // Epoxy
        epoxy_category: "Промышленный класс",
        epoxy_title: "Эпоксидные покрытия",
        epoxy_meta: "Высокопрочное бесшовное покрытие",
        epoxy_lead: "Двухкомпонентные полимерные системы для максимальной химической стойкости, механической прочности и бесшовной гигиены. Эталон промышленных и коммерческих полов в Израиле.",
        epoxy_h2_where: "Где применяется эпоксид",
        epoxy_p_where: "Эпоксидные полы идеальны для требовательных промышленных условий с химическим воздействием, интенсивным движением и строгими гигиеническими требованиями. От производственных цехов до фармацевтики — эпоксид обеспечивает бескомпромиссную производительность.",
        epoxy_app1_title: "Производственные цеха",
        epoxy_app1_desc: "Тяжёлое оборудование, погрузчики, масла и СОЖ. Самовыравнивающиеся или кварцевые системы 3-5мм.",
        epoxy_app2_title: "Склады и логистика",
        epoxy_app2_desc: "Зоны интенсивного движения, стойкость к рохлям, разметка. Кварцевые системы для долговечности.",
        epoxy_app3_title: "Пищевая промышленность",
        epoxy_app3_desc: "Очищаемые смоляные системы с опцией закруглённых плинтусов. Для горячей мойки и термошока чаще лучше PU-цемент.",
        epoxy_app4_title: "Фармацевтика и чистые помещения",
        epoxy_app4_desc: "Опции ESD-контроля, бесшовная поверхность и химстойкие финиши, когда это требуется спецификацией.",
        epoxy_h2_substrate: "Подготовка основания",
        epoxy_p_substrate: "Эпоксидные системы связываются механически и химически с основанием. Правильная подготовка — залог долговечности. Наша команда обеспечивает оптимальную подготовку каждой поверхности.",
        epoxy_sub1: "<strong>Дробеструйная обработка</strong> — Создаёт оптимальный профиль (CSP 3-5) и удаляет цементное молочко",
        epoxy_sub2: "<strong>Алмазная шлифовка</strong> — Для тонких систем или где дробеструйка невозможна",
        epoxy_sub3: "<strong>Ремонт трещин</strong> — Структурные трещины заполняются гибким эпоксидом, волосяные — проникающим праймером",
        epoxy_sub4: "<strong>Тест влажности</strong> — Хлоркальциевый и RH-зондовый тест по ASTM F1869/F2170",
        epoxy_sub5: "<strong>Удаление загрязнений</strong> — Масла, жиры, отвердители должны быть полностью удалены",
        epoxy_h2_system: "Архитектура системы",
        epoxy_p_system: "Каждая эпоксидная укладка следует точной многослойной системе, где каждый компонент работает на максимальную производительность и долговечность.",
        epoxy_layer1_title: "Грунтовочный слой",
        epoxy_layer1_desc: "Низковязкий эпоксид проникает в поры основания, укрепляет слабые слои и обеспечивает химическую связь для последующих слоёв. Расход: 0.15-0.25 кг/м².",
        epoxy_layer2_title: "Основной слой / Посыпка",
        epoxy_layer2_desc: "Самовыравнивающийся или затираемый эпоксидный раствор набирает толщину. Для интенсивного движения кварц посыпается во влажную смолу для механического сцепления и износостойкости.",
        epoxy_layer3_title: "Финишный слой",
        epoxy_layer3_desc: "Прозрачный или пигментированный топкоут инкапсулирует заполнитель, обеспечивает UV-стабильность (алифатические системы) и определяет итоговый глянец и химстойкость.",
        epoxy_h2_variants: "Варианты систем",
        epoxy_p_variants: "Мы предлагаем множество конфигураций эпоксидных систем под ваши требования:",
        epoxy_var1_title: "Самовыравнивающийся",
        epoxy_var1_desc: "Гладкая бесшовная поверхность. Толщина 2-3мм. Для лёгкого-среднего движения, чистых помещений.",
        epoxy_var2_title: "Кварцевая посыпка",
        epoxy_var2_desc: "Цветной кварц для текстуры и долговечности. 3-5мм. Интенсивное движение, декоративные опции.",
        epoxy_var3_title: "Растворная система",
        epoxy_var3_desc: "Толстослойная затираемая система. 6-12мм. Экстремальная ударо- и термостойкость.",
        epoxy_var4_title: "ESD/Токопроводящий",
        epoxy_var4_desc: "Контроль электростатического разряда. Электроника, дата-центры, операционные.",
        epoxy_h2_advantages: "Ключевые преимущества",
        epoxy_adv1: "<strong>Химическая стойкость</strong> — Система подбирается под масла, топливо, моющие средства и отдельные кислоты/щёлочи после проверки списка воздействий.",
        epoxy_adv2: "<strong>Бесшовность и гигиена</strong> — Нет швов и затирки, где могут скапливаться бактерии. Легко мыть и дезинфицировать.",
        epoxy_adv3: "<strong>Механическая прочность</strong> — Высокая прочность на сжатие (80+ МПа), ударо- и износостойкость.",
        epoxy_adv4: "<strong>Гибкость дизайна</strong> — Неограниченные цвета, металлик-эффекты, флейк-системы, логотипы и разметка.",
        epoxy_adv5: "<strong>Быстрый возврат в эксплуатацию</strong> — Пешеходная нагрузка через 24 часа, полная — через 7 дней.",
        epoxy_adv6: "<strong>Срок службы</strong> — Зависит от подготовки основания, трафика, химии, режима уборки и обслуживания.",
