        // Microtopping
        micro_category: "Архитектурное покрытие",
        micro_title: "Микротоппинг",
        micro_meta: "Ультратонкое цементное покрытие",
        micro_lead: "Ультратонкое полимерно-модифицированное цементное покрытие, которое преображает существующие поверхности в бесшовные современные полы. Выбор архитекторов для минималистичных интерьеров с индустриальным характером.",
        micro_h2_where: "Где применяется микротоппинг",
        micro_p_where: "Микротоппинг создаёт бесшовные, текучие поверхности, которые определяют современные архитектурные пространства. Минимальная толщина делает его идеальным для реновации, где критична высота пола.",
        micro_app1_title: "Премиум жильё",
        micro_app1_desc: "Гостиные, кухни, ванные. Непрерывная поверхность по всему дому. Совместим с тёплым полом.",
        micro_app2_title: "Ритейл и шоурумы",
        micro_app2_desc: "Нейтральный фон, подчёркивающий товар. Простой уход для зон с интенсивным трафиком.",
        micro_app3_title: "Гостиничный бизнес",
        micro_app3_desc: "Отели, рестораны, кафе. Создаёт изысканную атмосферу с индустриальными нотками.",
        micro_app4_title: "Реновация",
        micro_app4_desc: "Укладка поверх существующей плитки, бетона или стяжки без демонтажа. Минимальный подъём уровня пола.",
        micro_h2_substrate: "Подготовка основания",
        micro_p_substrate: "Микротоппинг тонкий (2-3мм), поэтому дефекты основания проявляются. Подготовка поверхности определяет итоговое качество.",
        micro_sub1: "<strong>Существующая плитка</strong> — Можно укладывать поверх, если прочная. Швы заполняются, поверхность шлифуется",
        micro_sub2: "<strong>Бетон</strong> — Должен быть ровным, без цементного молочка, трещины заполнены гибким составом",
        micro_sub3: "<strong>Стяжки</strong> — Самовыравнивающаяся смесь для достижения нужной ровности (SR1-SR2)",
        micro_sub4: "<strong>Адгезионный праймер</strong> — Системный праймер обеспечивает сцепление с различными основаниями",
        micro_sub5: "<strong>Армирование трещин</strong> — Стеклосетка укладывается на деформационных швах и заполненных трещинах",
        micro_h2_process: "Процесс нанесения",
        micro_p_process: "Микротоппинг наносится в несколько тонких слоёв, каждый прорабатывается вручную для создания желаемой текстуры.",
        micro_layer1_title: "Базовый слой",
        micro_layer1_desc: "Первый слой полимерно-модифицированного цемента наносится кельмой. Создаёт основу, заполняет мелкие неровности. При необходимости укладывается стеклосетка.",
        micro_layer2_title: "Финишный слой",
        micro_layer2_desc: "Тонкий декоративный слой наносится и прорабатывается вручную для создания желаемой текстуры — от гладкой до вариативной, в зависимости от техники.",
        micro_layer3_title: "Система герметика",
        micro_layer3_desc: "Двухкомпонентный полиуретановый или эпоксидный герметик обеспечивает стойкость к пятнам и долговечность. Разные степени глянца: матовый, сатиновый, глянцевый.",
        micro_h2_finishes: "Варианты отделки",
        micro_p_finishes: "Каждый пол из микротоппинга можно настроить под желаемую эстетику:",
        micro_var1_title: "Натуральный цемент",
        micro_var1_desc: "Классические серые тона с лёгкими вариациями. Сырая индустриальная эстетика.",
        micro_var2_title: "Тонированный",
        micro_var2_desc: "Интегральные пигменты создают тёплые или холодные тона — от угольного до тёплого тауп.",
        micro_var3_title: "Облачный эффект",
        micro_var3_desc: "Намеренные следы кельмы создают движение и глубину. Ремесленный характер.",
        micro_var4_title: "Однородный",
        micro_var4_desc: "Нанесение распылением для более равномерного вида. Современный, минималистичный.",
        micro_h2_advantages: "Ключевые преимущества",
        micro_adv1: "<strong>Минимальная толщина</strong> — Всего 2-3мм. Не нужно подрезать двери, нет проблем с переходами и уровнем пола.",
        micro_adv2: "<strong>Бесшовная непрерывность</strong> — Нет швов, нет затирки. Поверхность течёт из комнаты в комнату.",
        micro_adv3: "<strong>Дружелюбен к реновации</strong> — Укладка поверх существующих полов без демонтажа. Быстрее, чище, меньше шума.",
        micro_adv4: "<strong>Уникальный характер</strong> — Ручное нанесение, ремесленная отделка. Каждый пол единственный в своём роде.",
        micro_adv5: "<strong>Тёплый пол</strong> — Отличная теплопроводность. Тоньше плитки — быстрее нагрев.",
        micro_adv6: "<strong>Универсальность применения</strong> — Полы, стены, лестницы, столешницы — единый материальный язык.",
        micro_h2_maintenance: "Протокол обслуживания",
        micro_p_maintenance: "Правильно загерметизированный микротоппинг долговечен и прост в уходе. Герметик выполняет основную работу — защищает цементную поверхность от пятен и износа.",
        micro_maint_daily: "Подметание или пылесос для удаления песка. Влажная уборка по необходимости с нейтральным pH-очистителем.",
