        mma_app2_desc: "Отверждается при температуре до -30°C. Морозильные камеры, холодовые цепи, рефрижераторные склады.",
        mma_app3_title: "Ритейл реновация",
        mma_app3_desc: "Реконструкция ТЦ, переоборудование супермаркетов — укладка ночью, открытие утром.",
        mma_app4_title: "Медицина",
        mma_app4_desc: "Медицинские и чувствительные объекты только с планом вентиляции, запаха и поэтапного доступа.",
        mma_h2_speed: "Скорость без компромиссов",
        mma_p_speed: "Быстрое отверждение MMA не означает сокращений в подготовке. Поверхность готовится по тем же строгим стандартам, что и для эпоксида.",
        mma_prep1: "<strong>Дробеструйная обработка</strong> — Предпочтительный метод для оптимального профиля. Можно продолжать сразу",
        mma_prep2: "<strong>Алмазная шлифовка</strong> — Альтернатива, где дробеструйка невозможна",
        mma_prep3: "<strong>Устойчивость к влаге</strong> — Более терпима, чем эпоксид, но избыточная влага всё же требует управления",
        mma_prep4: "<strong>Холодные условия</strong> — Не требуется обогрев для укладки при минусовых температурах",
        mma_prep5: "<strong>Быстрое отверждение праймера</strong> — MMA-праймеры отверждаются за 30-60 минут, позволяя завершить систему за день",
        mma_h2_system: "Архитектура системы",
        mma_p_system: "MMA-системы следуют схожему многослойному подходу с эпоксидом, но с радикально более быстрым отверждением на каждом этапе.",
        mma_layer1_title: "Реактивный праймер",
        mma_layer1_desc: "MMA-праймер проникает и герметизирует основание. Отверждается за 30-60 минут при 20°C, пропорционально быстрее при более высоких температурах.",
        mma_layer2_title: "Основной слой",
        mma_layer2_desc: "Самовыравнивающаяся или посыпная MMA-смола. Посыпка заполнителем для противоскольжения при необходимости. Отверждается за 1-2 часа.",
        mma_layer3_title: "Финишный слой",
        mma_layer3_desc: "Прозрачный или пигментированный топкоут. UV-стабильные алифатические формулы для наружного применения или ярко освещённых помещений. Полное отверждение за 1-2 часа.",
        mma_h2_variants: "Варианты систем",
        mma_p_variants: "MMA доступен в различных конфигурациях под ваши конкретные требования:",
        mma_var1_title: "Самовыравнивающийся",
        mma_var1_desc: "Гладкая бесшовная поверхность. 2-3мм. Быстрая укладка для минимального простоя.",
        mma_var2_title: "Кварцевая посыпка",
        mma_var2_desc: "Цветной кварц для долговечности и противоскольжения. Общая толщина 3-4мм.",
        mma_var3_title: "Текстурный",
        mma_var3_desc: "Текстурная посыпка для влажных зон, пандусов и наружного применения.",
        mma_var4_title: "Декоративный флейк",
        mma_var4_desc: "Посыпка цветными чипсами для эстетики. Популярен в ритейле и коммерции.",
        mma_h2_advantages: "Ключевые преимущества",
        mma_adv1: "<strong>Быстрое отверждение</strong> — Для коротких окон остановки; срок допуска нагрузки зависит от системы и температуры на объекте.",
        mma_adv2: "<strong>Отверждение при низких температурах</strong> — Укладка от -30°C до +35°C. Не нужен обогрев для холодных складов или зимних работ.",
        mma_adv3: "<strong>UV-стабильность</strong> — Алифатический MMA не желтеет и не мелится. Подходит для наружного применения.",
        mma_adv4: "<strong>Химическая стойкость</strong> — Отличная устойчивость к кислотам, щелочам и многим растворителям.",
        mma_adv5: "<strong>Гибкость</strong> — Гибче эпоксида, перекрывает волосяные трещины, адаптируется к подвижкам основания.",
        mma_adv6: "<strong>Меньше простоя</strong> — Главное преимущество — поэтапная работа, когда длинная остановка нереальна.",
        mma_h2_maintenance: "Протокол обслуживания",
        mma_p_maintenance: "MMA-полы обеспечивают производительность, сопоставимую с эпоксидом, при значительно более быстрой укладке. Уход прост.",
        mma_maint_daily: "Подметание или автоскрабер для удаления мусора. Точечная уборка разливов по мере возникновения.",
        mma_maint_weekly: "Машинная мойка с нейтральным pH-очистителем. Тщательное ополаскивание.",
        mma_maint_quarterly: "Глубокая очистка и осмотр. Проверка состояния топкоута в зонах износа.",
        mma_maint_asneeded: "Возможно быстрое перекрытие — MMA-топкоут можно нанести с минимальной подготовкой.",
        mma_cta_title: "Нужен минимальный простой?",
        mma_cta_text: "Обсудим, как MMA решит вашу задачу быстрой укладки.",
        mma_specs_title: "Технические характеристики",
        mma_spec_thickness: "Толщина системы",
        mma_spec_traffic: "Готовность к нагрузке",
        mma_spec_primer: "Отверждение праймера",
        mma_temp_title: "Диапазон температур",
        mma_temp_min: "Мин. температура укладки",
