        // Terrazzo
        terrazzo_category: "Премиум декор",
        terrazzo_title: "Терраццо",
        terrazzo_meta: "Вечная красота заполнителей",
        terrazzo_lead: "Мраморные, стеклянные или каменные заполнители в цементной или эпоксидной матрице — затем шлифовка и полировка, раскрывающие глубину и характер. Пол с душой, который может служить поколениям.",
        terrazzo_h2_where: "Где терраццо сияет",
        terrazzo_p_where: "Терраццо веками был символом элегантности и долговечности. Сегодня он остаётся выбором для пространств, где дизайнерское воздействие и долговечность приоритетны.",
        terrazzo_app1_title: "Аэропорты и транспорт",
        terrazzo_app1_desc: "Долговечность при миллионах проходов. Навигационные паттерны, логотипы, интеграция бренда. Низкая стоимость владения.",
        terrazzo_app2_title: "Люксовый ритейл",
        terrazzo_app2_desc: "Полы-заявления, которые усиливают бренд-опыт. Индивидуальный подбор заполнителей и паттернов.",
        terrazzo_app3_title: "Отели и лобби",
        terrazzo_app3_desc: "Парадные входные заявления. Сочетание долговечности с визуальным воздействием. Исторический или современный.",
        terrazzo_app4_title: "Медицина",
        terrazzo_app4_desc: "Бесшовность, гигиеничность, лёгкость уборки. Соответствие инфекционному контролю. Пожизненная долговечность снижает затраты на замену.",
        terrazzo_h2_substrate: "Подготовка основания",
        terrazzo_p_substrate: "Терраццо — постоянная инсталляция, требующая надлежащей структурной поддержки. Подготовка основания зависит от типа системы, но критична для долгосрочной работы.",
        terrazzo_sub1: "<strong>Цементное терраццо (традиционное)</strong> — Требует песчано-цементной подложки поверх гидроизоляции. Общая толщина 25-50мм",
        terrazzo_sub2: "<strong>Эпоксидное терраццо (тонкослойное)</strong> — Наносится прямо на подготовленный бетон. Общая толщина 10-12мм",
        terrazzo_sub3: "<strong>Разделительные профили</strong> — Латунные, цинковые или пластиковые профили контролируют трещины и создают дизайнерские паттерны",
        terrazzo_sub4: "<strong>Деформационные швы</strong> — Должны совпадать со структурными швами. Заполняются гибким герметиком",
        terrazzo_sub5: "<strong>Контроль влаги</strong> — Критичен для эпоксидных систем. Пароизоляция или митигация при RH >75%",
        terrazzo_h2_process: "Процесс терраццо",
        terrazzo_p_process: "Каждая укладка терраццо следует проверенному временем процессу, превращающему сырьё в долговечные произведения искусства.",
        terrazzo_layer1_title: "Заливка и укладка",
        terrazzo_layer1_desc: "Матрица (цемент или эпоксид) смешивается с выбранными заполнителями, заливается между разделительными профилями и распределяется до заданной глубины. Заполнители посыпаются вручную для плотности.",
        terrazzo_layer2_title: "Шлифовка",
        terrazzo_layer2_desc: "Последовательная шлифовка алмазными сегментами раскрывает грани заполнителей. Множество проходов от грубых (40 грит) до тонких (200+ грит) создают гладкую поверхность.",
        terrazzo_layer3_title: "Шпаклёвка и полировка",
        terrazzo_layer3_desc: "Поры заполняются подходящей шпаклёвкой, затем полировка до итогового блеска. Проникающий герметик защищает, не меняя вид.",
        terrazzo_h2_aggregates: "Варианты заполнителей",
        terrazzo_p_aggregates: "Красота терраццо в бесконечных дизайнерских возможностях через выбор заполнителей:",
        terrazzo_var1_title: "Мраморная крошка",
        terrazzo_var1_desc: "Классический заполнитель терраццо. Размеры от 0 (мелкий) до 8 (крупный). Естественные цветовые вариации.",
        terrazzo_var2_title: "Стекло",
        terrazzo_var2_desc: "Переработанное или первичное стекло неограниченных цветов. Отражающий блеск, экологичный вариант.",
        terrazzo_var3_title: "Перламутр",
        terrazzo_var3_desc: "Измельчённая ракушка для переливающегося эффекта. Люксовые жилые и гостиничные применения.",
        terrazzo_var4_title: "Смешанный / На заказ",
        terrazzo_var4_desc: "Комбинируйте заполнители для уникальных эффектов. Ракушки, металл, зеркало — возможности безграничны.",
        terrazzo_h2_advantages: "Ключевые преимущества",
        terrazzo_adv1: "<strong>Исключительная долговечность</strong> — 50+ лет службы. Многие полы терраццо 1920-х годов работают до сих пор.",
        terrazzo_adv2: "<strong>Свобода дизайна</strong> — Неограниченные цвета, паттерны, логотипы и инкрустации. Истинные индивидуальные возможности.",
        terrazzo_adv3: "<strong>Низкая стоимость владения</strong> — Высокая начальная стоимость компенсируется десятилетиями службы. Реставрируется, а не заменяется.",
        terrazzo_adv4: "<strong>Экологичность</strong> — Переработанное стекло и постпотребительские заполнители. VOC-free цементные системы. LEED-кредиты.",
        terrazzo_adv5: "<strong>Бесшовность и гигиена</strong> — Нет затирочных швов. Разделительные профили интегральны. Легко мыть и обслуживать.",
        terrazzo_adv6: "<strong>Реставрируемость</strong> — Можно перешлифовать и переполировать до исходного состояния. Пол, который улучшается с возрастом.",
