        rubber_lead: "Вулканизированные резиновые покрытия для сред, где важны комфорт, безопасность и звукопоглощение. Доступны в рулонах, плитках или наливных системах под любое применение.",
        rubber_h2_where: "Где резина превосходит",
        rubber_p_where: "Резиновые покрытия обеспечивают идеальное сочетание долговечности, комфорта и безопасности для требовательных сред, где люди стоят, двигаются и работают.",
        rubber_app1_title: "Фитнес-центры",
        rubber_app1_desc: "Спортзалы, тренажёрные залы, кроссфит. Поглощение ударов, защита от падающих весов, лёгкая уборка.",
        rubber_app2_title: "Медицина",
        rubber_app2_desc: "Больницы, клиники, дома престарелых. Антиусталость для персонала, противоскольжение, звукопоглощение.",
        rubber_app3_title: "Образование",
        rubber_app3_desc: "Школы, университеты, библиотеки. Долговечность, тишина, безопасность. Экологичные переработанные варианты.",
        rubber_app4_title: "Детские площадки и рекреация",
        rubber_app4_desc: "Безопасные покрытия для игровых зон. Наливные резиновые системы с рейтингом высоты падения.",
        rubber_h2_substrate: "Подготовка основания",
        rubber_p_substrate: "Резиновые покрытия можно приклеивать, укладывать свободно или монтировать на подложку. Требования к основанию зависят от метода укладки.",
        rubber_sub1: "<strong>Полное приклеивание</strong> — Основание должно быть ровным (SR1-SR2), сухим и чистым от загрязнений. Лучше для постоянных укладок",
        rubber_sub2: "<strong>Свободная укладка</strong> — Тяжёлые резиновые плитки можно укладывать без клея. Позволяет замену и доступ к основанию",
        rubber_sub3: "<strong>Замковые плитки</strong> — Клей не требуется. Быстрый монтаж для спортзалов и временных применений",
        rubber_sub4: "<strong>Наливная резина</strong> — EPDM-гранулы с полиуретановым связующим. Бесшовная, любая толщина, рейтинг для площадок",
        rubber_sub5: "<strong>Влажность</strong> — Резина непроницаема; избыточная влага требует решения для предотвращения плесени под покрытием",
        rubber_h2_types: "Типы резиновых покрытий",
        rubber_p_types: "Мы предлагаем различные технологии резиновых покрытий под ваши конкретные требования.",
        rubber_layer1_title: "Вулканизированная резина",
        rubber_layer1_desc: "Заводские листы или плитки. Процесс вулканизации создаёт долговечный, упругий продукт. Доступна в натуральных или синтетических формулах.",
        rubber_layer2_title: "Переработанная резина",
        rubber_layer2_desc: "Из переработанных шин. Доступна как плитки, рулоны или наливная. Отлично для спортзалов и площадок. Экологичный выбор.",
        rubber_layer3_title: "Наливной EPDM",
        rubber_layer3_desc: "EPDM-гранулы с полиуретановым связующим, заливаемые на месте. Бесшовная, любая толщина, любой цвет. Идеальна для площадок и спортивных покрытий.",
        rubber_h2_patterns: "Рисунки поверхности",
        rubber_p_patterns: "Различные текстуры поверхности обеспечивают разные уровни противоскольжения и эстетические опции:",
        rubber_var1_title: "Гладкая",
        rubber_var1_desc: "Легко моется. Распространена в медицине и ритейле. Требует хорошего дренажа для влажных зон.",
        rubber_var2_title: "Диски / Шипы",
        rubber_var2_desc: "Классический вид резиновых покрытий. Улучшенное противоскольжение. Транспорт и промышленность.",
        rubber_var3_title: "Молотковая",
        rubber_var3_desc: "Текстура для противоскольжения и визуального интереса. Хорошо скрывает следы износа.",
        rubber_var4_title: "На заказ",
        rubber_var4_desc: "Логотипы, паттерны, навигация интегрированы в пол. Безграничные дизайнерские возможности.",
        rubber_h2_advantages: "Ключевые преимущества",
        rubber_adv1: "<strong>Комфорт и антиусталость</strong> — Амортизирующая поверхность снижает нагрузку на ноги и спину. Критично для стоячей работы.",
        rubber_adv2: "<strong>Звукопоглощение</strong> — Значительно снижает ударный шум и воздушную звукопередачу. Тишина в помещениях.",
        rubber_adv3: "<strong>Противоскольжение</strong> — Естественное сцепление даже во влажном состоянии. Отличный профиль безопасности для зон с интенсивным движением.",
        rubber_adv4: "<strong>Поглощение ударов</strong> — Защищает падающие предметы и смягчает падения. Критично для спортзалов и игровых зон.",
        rubber_adv5: "<strong>Экологичные опции</strong> — Переработанные шины. Натуральный каучук из устойчивых источников. Долгий срок службы.",
        rubber_adv6: "<strong>Простой уход</strong> — Подметание и мытьё. Вощение не требуется. Упругая поверхность устойчива к пятнам.",
