        rest_lead: "Продление срока службы существующих полов через профессиональную реставрацию, перекрытие и обновление герметика. Экономичное обслуживание, которое восстанавливает вид и защиту за долю стоимости замены.",
        rest_h2_what: "Что мы реставрируем",
        rest_p_what: "Наши услуги реставрации охватывают все основные системы напольных покрытий. Мы индивидуально оцениваем каждый пол для определения наиболее эффективного подхода.",
